-- Initial schema.
-- Primary keys are UUIDv7 generated by the application. Every table carries
-- tenant_id; a single default tenant is seeded until multi-tenancy lands.
-- Status/role columns use TEXT + CHECK instead of enums so values can be
-- added without type migrations.

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE tenants (
    id          UUID PRIMARY KEY,
    name        TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO tenants (id, name) VALUES ('00000000-0000-0000-0000-000000000001', 'default');

-- Knowledge base ----------------------------------------------------------

CREATE TABLE knowledge_bases (
    id          UUID PRIMARY KEY,
    tenant_id   UUID NOT NULL REFERENCES tenants (id),
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX knowledge_bases_tenant_idx ON knowledge_bases (tenant_id, created_at DESC);

CREATE TABLE kb_documents (
    id            UUID PRIMARY KEY,
    tenant_id     UUID NOT NULL REFERENCES tenants (id),
    kb_id         UUID NOT NULL REFERENCES knowledge_bases (id) ON DELETE CASCADE,
    filename      TEXT NOT NULL,
    content_type  TEXT,
    size_bytes    BIGINT,
    storage_key   TEXT,
    status        TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'processing', 'ready', 'failed')),
    error         TEXT,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX kb_documents_kb_idx ON kb_documents (kb_id, created_at DESC);

CREATE TABLE kb_chunks (
    id           UUID PRIMARY KEY,
    tenant_id    UUID NOT NULL REFERENCES tenants (id),
    kb_id        UUID NOT NULL REFERENCES knowledge_bases (id) ON DELETE CASCADE,
    document_id  UUID NOT NULL REFERENCES kb_documents (id) ON DELETE CASCADE,
    seq          INTEGER NOT NULL,
    content      TEXT NOT NULL,
    token_count  INTEGER NOT NULL,
    embedding    vector(1024) NOT NULL,
    UNIQUE (document_id, seq)
);
CREATE INDEX kb_chunks_kb_idx ON kb_chunks (kb_id);
CREATE INDEX kb_chunks_embedding_hnsw ON kb_chunks
    USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);

-- Calls -----------------------------------------------------------------------

CREATE TABLE calls (
    id                 UUID PRIMARY KEY,
    tenant_id          UUID NOT NULL REFERENCES tenants (id),
    to_number          TEXT NOT NULL,
    lead_name          TEXT NOT NULL,
    system_prompt      TEXT NOT NULL,
    kb_id              UUID REFERENCES knowledge_bases (id) ON DELETE SET NULL,
    language           TEXT NOT NULL DEFAULT 'auto',   -- requested: 'auto' or BCP-47
    detected_language  TEXT,                           -- from STT auto-detect
    voice              TEXT,                           -- per-call speaker override
    greeting           TEXT,
    max_duration_secs  INTEGER NOT NULL DEFAULT 300 CHECK (max_duration_secs BETWEEN 10 AND 3600),
    status             TEXT NOT NULL DEFAULT 'queued'
                       CHECK (status IN ('queued', 'ringing', 'in_progress', 'completed',
                                         'failed', 'no_answer', 'busy')),
    plivo_call_uuid    TEXT,
    started_at         TIMESTAMPTZ,
    answered_at        TIMESTAMPTZ,
    ended_at           TIMESTAMPTZ,
    duration_secs      INTEGER,
    end_reason         TEXT,
    recording_key      TEXT,
    extracted_fields   JSONB,
    -- Usage and estimated cost (₹, excl. GST), filled when the call ends.
    stt_seconds        DOUBLE PRECISION NOT NULL DEFAULT 0,
    tts_chars          INTEGER NOT NULL DEFAULT 0,
    llm_usage          JSONB NOT NULL DEFAULT '{}'::jsonb,  -- {model: {prompt_tokens, cached_prompt_tokens, completion_tokens}}
    cost_inr           DOUBLE PRECISION NOT NULL DEFAULT 0,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX calls_tenant_created_idx ON calls (tenant_id, created_at DESC);
CREATE UNIQUE INDEX calls_plivo_uuid_idx ON calls (plivo_call_uuid) WHERE plivo_call_uuid IS NOT NULL;

CREATE TABLE call_turns (
    id           UUID PRIMARY KEY,
    tenant_id    UUID NOT NULL REFERENCES tenants (id),
    call_id      UUID NOT NULL REFERENCES calls (id) ON DELETE CASCADE,
    seq          INTEGER NOT NULL,
    role         TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'tool')),
    text         TEXT NOT NULL,
    language     TEXT,
    interrupted  BOOLEAN NOT NULL DEFAULT false,  -- assistant turn cut by barge-in (text = what was played)
    started_at   TIMESTAMPTZ NOT NULL,
    ended_at     TIMESTAMPTZ,
    UNIQUE (call_id, seq)
);

-- speech_end_ms is milliseconds since the call was answered; the other
-- *_ms columns are offsets from that speech end.
CREATE TABLE turn_latency (
    tenant_id            UUID NOT NULL REFERENCES tenants (id),
    call_id              UUID NOT NULL REFERENCES calls (id) ON DELETE CASCADE,
    turn_seq             INTEGER NOT NULL,
    speech_end_ms        INTEGER,
    stt_final_ms         INTEGER,
    llm_first_token_ms   INTEGER,
    tts_first_byte_ms    INTEGER,
    first_audio_sent_ms  INTEGER,
    spoken_chars         INTEGER NOT NULL DEFAULT 0,
    cap_triggered        BOOLEAN NOT NULL DEFAULT false,
    llm_model            TEXT,
    llm_attempts         SMALLINT NOT NULL DEFAULT 1,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (call_id, turn_seq)
);

CREATE TABLE call_followups (
    id          UUID PRIMARY KEY,
    tenant_id   UUID NOT NULL REFERENCES tenants (id),
    call_id     UUID NOT NULL REFERENCES calls (id) ON DELETE CASCADE,
    topic       TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX call_followups_call_idx ON call_followups (call_id);

-- Caches and bookkeeping -----------------------------------------------------

-- hash = sha256(model | speaker | language | codec | pace | text), hex.
CREATE TABLE tts_cache (
    tenant_id    UUID NOT NULL REFERENCES tenants (id),
    hash         TEXT NOT NULL,
    model        TEXT NOT NULL,
    speaker      TEXT NOT NULL,
    language     TEXT NOT NULL,
    text         TEXT NOT NULL,
    storage_key  TEXT NOT NULL,
    byte_len     INTEGER NOT NULL,
    duration_ms  INTEGER NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, hash)
);

-- status_code/response are NULL while the first request is still running.
CREATE TABLE idempotency_keys (
    tenant_id     UUID NOT NULL REFERENCES tenants (id),
    endpoint      TEXT NOT NULL,
    key           TEXT NOT NULL CHECK (length(key) BETWEEN 1 AND 255),
    request_hash  TEXT NOT NULL,
    status_code   SMALLINT,
    response      JSONB,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, endpoint, key)
);
CREATE INDEX idempotency_keys_created_idx ON idempotency_keys (created_at);
